    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        let started = now.seconds;
        // Clamp to 9999-12-31 so the year always has four digits.
        let secs = started.min(253_402_300_799) as i64;
        let (y, m, d) = civil_from_days(secs / 86_400);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started,
        }
    }
}

